// [WSCoop] Per-player harvesting: each player gathers level-placed nodes for themselves; the node
// stays up for everyone else (and regrows for this player after its usual respawn time).
if (Harvestable != nullptr && Harvestable.IsActivated() && WSCoopLoot::IsPerPlayerHarvest(Harvestable))
{
    if (WSCoopLoot::BlockRepeatHarvest(Harvestable, Player))
        return;
    if (DoubleDropChanceAttribute.IsValid())
        TryDoubleDrop(Context);
    GrantLoot(Player, LootComponent);
    WSCoopLoot::Gathered(Harvestable, Player); // record + pickup feedback / hide on their screen
    return;
}

TArray<UItemStack> Loot = LootComponent.GenerateLoot();
// [WSCoop] Coven synergy: chance of a bonus roll per nearby coven member.
if (WSCoopProgression::RollCovenBonusHarvest(Player))
{
    Loot.Append(LootComponent.GenerateLoot());
    WSCoop::Info(f"Coven harvest bonus for {WSCoop::PlayerName(Player)}");
}
